<?php/** * H5服务 */namespace app\api\service\business;use app\api\service\CommService;use app\api\service\public\SmsService;use app\common\model\business\MallCustomer;class MobileService extends CommService{    protected $category = 'h5';    public function __construct($param)    {        parent::_initialize($param);    }    public function autoLogin()    {        $this->param['openid'] = $where['openid'] = md5(request()->getRealIp() . time());        $this->data = $this->doLoginService($where, $this->param, true);        return $this->data;    }    private function doLoginService($where, $param, $autoLogin = false)    {        $MallCustomer = new MallCustomer();        $user_info = $MallCustomer->findUser($where);        $data['user_info'] = $MallCustomer->doLogin($user_info, $param, $autoLogin);        $data['current_time'] = get_datas();        return $data;    }    public function openidLogin()    {        $where['openid'] = $this->param['openid'];        $this->data = $this->doLoginService($where, $this->param);        return $this->data;    }    public function accountLogin()    {        $where['openid'] = $openid;        $this->param['openid'] = $openid;        $this->data = $this->doLoginService($where, $this->param, false);        return $this->data;    }}